import { Modal, Setting } from 'obsidian';
import type MarketplacePlugin from './main';
import { openMarketplaceModal } from './marketplaceModal';

const LOGO_DATA_URI =
	'data:image/png;base64,';

/** Shown once, right after the plugin is first loaded. See `hasSeenWelcome` in settings.ts. */
export function openWelcomeModal(plugin: MarketplacePlugin): void {
	new WelcomeModal(plugin).open();
}

class WelcomeModal extends Modal {
	private plugin: MarketplacePlugin;

	constructor(plugin: MarketplacePlugin) {
		super(plugin.app);
		this.plugin = plugin;
	}

	onOpen() {
		this.modalEl.addClass('marketplace-modal', 'marketplace-welcome');
		const { contentEl } = this;
		contentEl.empty();

		if (LOGO_DATA_URI) {
			contentEl.createEl('img', { cls: 'marketplace-welcome-logo', attr: { src: LOGO_DATA_URI } });
		}

		contentEl.createEl('h2', { text: 'Welcome to Notes hub!' });
		contentEl.createEl('p', {
			text: 'Thanks for installing! This plugin is still an early version, so expect some rough edges here and there.',
		});
		contentEl.createEl('p', {
			text: "Once you've got a folder of notes, a template, or a course you're proud of, we'd love for you to publish it and share it with others.",
		});

		new Setting(contentEl).addButton((button) =>
			button
				.setButtonText("Let's share!")
				.setCta()
				.onClick(() => {
					this.close();
					openMarketplaceModal(this.plugin);
				}),
		);
	}

	onClose() {
		this.contentEl.empty();
	}
}
